const services=[{id:'web',name:'Web sitesi',icon:'▣',price:25000,desc:'Markanızı anlatan, hızlı ve tüm ekranlara uyumlu web deneyimleri.'},{id:'mobile',name:'Mobil uygulama',icon:'▯',price:90000,desc:'Fikrinizi iOS ve Android’de kullanıcılarınızla buluşturun.'},{id:'erp',name:'ERP çözümleri',icon:'▦',price:120000,desc:'Operasyon, stok ve kaynaklarınızı tek merkezden yönetin.'},{id:'crm',name:'CRM çözümleri',icon:'◎',price:65000,desc:'Müşteri ilişkilerinizi ve satış süreçlerinizi bir araya getirin.'},{id:'auto',name:'Otomasyon',icon:'⌘',price:35000,desc:'Tekrarlayan işleri otomatikleştirin. Zamanınızı işinize ayırın.'}];
const extras=[{id:'language',name:'Çoklu dil',price:7500},{id:'integration',name:'API entegrasyonu',price:15000},{id:'admin',name:'Yönetim paneli',price:12000}];
const money=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0}).format(n);let selected=new Set();try{const saved=JSON.parse(localStorage.getItem('wemacode-cart')||'[]');if(Array.isArray(saved))selected=new Set(saved.filter(id=>[...services,...extras].some(x=>x.id===id)))}catch{};
document.querySelector('#services').innerHTML=services.map(s=>`<article class="service-card"><span class="service-icon">${s.icon}</span><h3>${s.name}</h3><p>${s.desc}</p><a href="#proje" data-add="${s.id}">Projeye ekle <span>↗</span></a></article>`).join('');
document.querySelector('#choices').innerHTML=services.map(s=>`<button type="button" class="choice" data-id="${s.id}" aria-pressed="false"><span>${s.icon}</span><span><strong>${s.name}</strong><small>${money(s.price)}’den başlayan</small></span><span class="check">✓</span></button>`).join('');
document.querySelector('#extras').innerHTML=extras.map(s=>`<label><input type="checkbox" value="${s.id}">${s.name}<small>+${money(s.price)}</small></label>`).join('');
function items(){return [...services,...extras].filter(s=>selected.has(s.id))}function total(){return items().reduce((n,s)=>n+s.price,0)}
function render(){document.querySelectorAll('[data-id]').forEach(b=>b.setAttribute('aria-pressed',selected.has(b.dataset.id)));document.querySelectorAll('#extras input').forEach(i=>{i.checked=selected.has(i.value);i.disabled=!services.some(s=>selected.has(s.id))});document.querySelector('#count').textContent=services.filter(s=>selected.has(s.id)).length;document.querySelector('#total').textContent=money(total());document.querySelector('#basket-items').innerHTML=items().length?items().map(s=>`<div class="basket-row"><span>${s.name}</span><b>${money(s.price)}</b><button type="button" data-remove="${s.id}" aria-label="${s.name} seçimini kaldır">×</button></div>`).join(''):'<p class="empty">İlk adım sizden. İhtiyacınız olan çözümü seçin.</p>';try{localStorage.setItem('wemacode-cart',JSON.stringify([...selected]))}catch{}}
function toggle(id){selected.has(id)?selected.delete(id):selected.add(id);if(!services.some(s=>selected.has(s.id)))extras.forEach(s=>selected.delete(s.id));render()}
document.querySelector('#choices').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)toggle(b.dataset.id)});document.querySelector('#extras').addEventListener('change',e=>toggle(e.target.value));document.querySelector('#basket-items').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b)toggle(b.dataset.remove)});document.querySelectorAll('[data-add]').forEach(a=>a.addEventListener('click',()=>{selected.add(a.dataset.add);render()}));
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target);const summary=['WEMACODE — PROJE ÖZETİ','',`Ad soyad: ${form.get('name')}`,`E-posta: ${form.get('email')}`,`Şirket: ${form.get('company')||'Belirtilmedi'}`,'','SEÇİLEN ÇÖZÜMLER',...items().map(s=>`${s.name}: ${money(s.price)}`),...(!items().length?['Henüz bir çözüm seçilmedi.']:[]),'',`Örnek tahmini başlangıç bütçesi: ${money(total())} (KDV hariç)`,'Bu tutarlar örnektir, bağlayıcı teklif değildir.','', 'PROJE NOTU',form.get('message')].join('\n');const blob=new Blob(['\uFEFF'+summary],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='wemacode-proje-ozeti.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Proje özetiniz hazırlandı. Dosya indirmesi başlatıldı; herhangi bir talep gönderilmedi.'});document.querySelector('#year').textContent=new Date().getFullYear();render();
